package com.smartcoffee.infrastructure.idempotency;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant; import java.util.UUID;
@Entity @Table(schema="integration",name="api_idempotency_records",uniqueConstraints=@UniqueConstraint(name="uk_idempotency_command",columnNames={"scope","actor_type","actor_id","idempotency_key"}))
public class ApiIdempotencyRecord {
 @Id @Column(name="idempotency_record_id") private UUID id=UUID.randomUUID(); @Column(nullable=false) private String scope; @Column(name="actor_type",nullable=false) private String actorType; @Column(name="actor_id",nullable=false) private UUID actorId; @Column(name="idempotency_key",nullable=false) private UUID idempotencyKey; @Column(name="request_hash",nullable=false,length=64) private String requestHash; @Enumerated(EnumType.STRING) @Column(nullable=false) private IdempotencyStatus status; @Column(name="response_status") private Integer responseStatus; @JdbcTypeCode(SqlTypes.JSON) @Column(name="response_body",columnDefinition="jsonb") private String responseBody; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); @Column(name="expires_at",nullable=false) private Instant expiresAt; @Version private long version;
 protected ApiIdempotencyRecord(){} public static ApiIdempotencyRecord processing(String s,String a,UUID actor,UUID key,String hash,Instant expiry){var r=new ApiIdempotencyRecord();r.scope=s;r.actorType=a;r.actorId=actor;r.idempotencyKey=key;r.requestHash=hash;r.status=IdempotencyStatus.PROCESSING;r.expiresAt=expiry;return r;} public String requestHash(){return requestHash;} public IdempotencyStatus status(){return status;} public String responseBody(){return responseBody;} public Integer responseStatus(){return responseStatus;} public void complete(int status,String body){this.status=IdempotencyStatus.COMPLETED;this.responseStatus=status;this.responseBody=body;this.updatedAt=Instant.now();}
}

